     * Plain text of a page in logical order (used by Reading Mode).
     */
    fun `pageText`(`page`: kotlin.Int): kotlin.String
    
    fun `release`()
    
    /**
     * Renders a tile of a page laid out at `full_width`×`full_height` pixels.
