        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_reader_core_fn_free_reflowdoc(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_reader_core_fn_clone_reflowdoc(handle, status)
        }
    }

    
    /**
     * A complete HTML document for chapter `index`, sanitized, with `dir`/`lang`
     * set and a `<!--READER_HEAD-->` marker where the app injects its CSS/JS.
     * Returns (mime, html).
     */
    @Throws(ReaderException::class)override fun `chapter`(`index`: kotlin.UInt): Resource {
            return FfiConverterTypeResource.lift(
    callWithHandle {
    uniffiRustCallWithError(ReaderException) { _status ->
    UniffiLib.uniffi_reader_core_fn_method_reflowdoc_chapter(
        it,
        
        FfiConverterUInt.lower(`index`),_status)
}
    }
    )
    }
    

    
    /**
     * Index of the chapter served at `path`, if any.
     */override fun `chapterIndex`(`path`: kotlin.String): kotlin.UInt? {
            return FfiConverterOptionalUInt.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_reader_core_fn_method_reflowdoc_chapter_index(
        it,
        
        FfiConverterString.lower(`path`),_status)
}
    }
    )
    }
    

    
    /**
     * Plain text of a chapter (for text-to-speech / copy).
     */override fun `chapterText`(`index`: kotlin.UInt): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_reader_core_fn_method_reflowdoc_chapter_text(
        it,
        
        FfiConverterUInt.lower(`index`),_status)
}
    }
    )
    }
    

    override fun `cover`(): Resource? {
            return FfiConverterOptionalTypeResource.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_reader_core_fn_method_reflowdoc_cover(
        it,
        _status)
}
    }
    )
    }
    

    override fun `info`(): BookInfo {
            return FfiConverterTypeBookInfo.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_reader_core_fn_method_reflowdoc_info(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Any non-chapter resource (image, css, font…) by its book path.
     */override fun `resource`(`path`: kotlin.String): Resource? {
            return FfiConverterOptionalTypeResource.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_reader_core_fn_method_reflowdoc_resource(
        it,
        
        FfiConverterString.lower(`path`),_status)
}
    }
    )
    }
    

    
    /**
     * Searches all chapters. Diacritics and presentation forms are ignored;
     * for Uyghur books every Uyghur letter stays distinct and Latin (ULY)
     * queries are transliterated.
     */override fun `search`(`query`: kotlin.String, `maxHits`: kotlin.UInt): List<ReflowHit> {
            return FfiConverterSequenceTypeReflowHit.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_reader_core_fn_method_reflowdoc_search(
        it,
        
        FfiConverterString.lower(`query`),
        FfiConverterUInt.lower(`maxHits`),_status)
}
    }
    )
    }
    

    

    


    
    companion object {
        
    @Throws(ReaderException::class) fun `open`(`path`: kotlin.String): ReflowDoc {
            return FfiConverterTypeReflowDoc.lift(
    uniffiRustCallWithError(ReaderException) { _status ->
    UniffiLib.uniffi_reader_core_fn_constructor_reflowdoc_open(
    
        
        FfiConverterString.lower(`path`),_status)
}
    )
    }
    

        
    }
    
}


/**
 * @suppress
 */
public object FfiConverterTypeReflowDoc: FfiConverter<ReflowDoc, Long> {
    override fun lower(value: ReflowDoc): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): ReflowDoc {
        return ReflowDoc(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): ReflowDoc {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ReflowDoc) = 8UL

    override fun write(value: ReflowDoc, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



