sealed class ReaderException: kotlin.Exception() {
    
    class Io(
        
        val `msg`: kotlin.String
        ) : ReaderException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Unsupported(
        
        val `msg`: kotlin.String
        ) : ReaderException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Parse(
        
        val `msg`: kotlin.String
        ) : ReaderException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Pdf(
        
        val `msg`: kotlin.String
        ) : ReaderException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Password(
        ) : ReaderException() {
        override val message
            get() = ""
    }
    
    class Closed(
        ) : ReaderException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ReaderException> {
        override fun lift(error_buf: RustBuffer.ByValue): ReaderException = FfiConverterTypeReaderError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeReaderError : FfiConverterRustBuffer<ReaderException> {
    override fun read(buf: ByteBuffer): ReaderException {
        

        return when(buf.getInt()) {
            1 -> ReaderException.Io(
                FfiConverterString.read(buf),
                )
            2 -> ReaderException.Unsupported(
                FfiConverterString.read(buf),
                )
            3 -> ReaderException.Parse(
                FfiConverterString.read(buf),
                )
            4 -> ReaderException.Pdf(
                FfiConverterString.read(buf),
                )
            5 -> ReaderException.Password()
            6 -> ReaderException.Closed()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ReaderException): ULong {
        return when(value) {
            is ReaderException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is ReaderException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is ReaderException.Parse -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is ReaderException.Pdf -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is ReaderException.Password -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ReaderException.Closed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: ReaderException, buf: ByteBuffer) {
        when(value) {
            is ReaderException.Io -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is ReaderException.Unsupported -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is ReaderException.Parse -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is ReaderException.Pdf -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is ReaderException.Password -> {
                buf.putInt(5)
                Unit
            }
            is ReaderException.Closed -> {
                buf.putInt(6)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




