        val len = buf.getInt()
        return List<ReflowHit>(len) {
            FfiConverterTypeReflowHit.read(buf)
        }
    }

    override fun allocationSize(value: List<ReflowHit>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeReflowHit.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<ReflowHit>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeReflowHit.write(it, buf)
        }
    }
}




